    enunciado: "Observe o emprego da palavra \"se\" nos períodos a seguir:\nI. \"Analisam-se com rigor as emendas apresentadas ao orçamento.\"\nII. \"Precisa-se de técnicos experientes na secretaria legislativa.\"\nIII. \"Ninguém soube informar se a sessão extraordinária seria mantida.\"\nIV. \"O relator reservou-se o direito de revisar o texto antes da votação.\"\n\nRespectivamente, a partícula \"se\" funciona em I, II, III e IV como:",
