    sourceType: "Inédita Nível Top 10 (Padrão Selecon 2026)",
    enunciado: "Considere o período: \"Malgrado a exiguidade do prazo regimental, a comissão apresentou o substitutivo, porquanto a matéria demandava urgente adequação orçamentária.\"\nAssinale a reescrita que preserva INTEGRALMENTE o sentido original e a correção gramatical:",
