    enunciado: "Leia o período: \"O tribunal manteve a decisão administrativa, não se devendo, pois, falar em nulidade do certame, senão quando comprovada fraude documental.\"\nAssinale a alternativa que interpreta e reescreve CORRETAMENTE os valores coesivos de \"pois\" e \"senão\" no contexto:",
