      "Tanto no Word PT-BR quanto no Writer PT-BR, Ctrl + S aplica sublinhado e Ctrl + U centraliza o parágrafo selecionado.",
      "No Word PT-BR, Ctrl + T fecha o documento atual; no Writer PT-BR, Ctrl + T abre uma nova guia de impressão."
