    enunciado: "Numa planilha de controle de prazos regimentais, a célula A2 indica os dias decorridos (`12`), B2 indica o tipo de urgência (`\"Sim\"`) e C2 indica se há parecer anexado (`\"Não\"`). A célula D2 contém a fórmula:\n`=SE(E(A2>10; B2=\"Sim\"; C2=\"Sim\"); \"Pronta\"; SE(OU(A2>15; C2=\"Não\"); \"Atrasada ou Pendente\"; \"Regular\"))`\n\nO texto exibido na célula D2 será:",
