    enunciado: "Ao utilizar navegadores modernos (Google Chrome, Microsoft Edge e Mozilla Firefox) em estações compartilhadas, um servidor fechou acidentalmente uma guia importante e depois abriu uma janela privada para acessar o webmail. Sobre atalhos e o real alcance da navegação anônima/privada, assinale a alternativa CORRETA:",
