    sourceType: "Inédita Nível Top 10 (Padrão Selecon 2026)",
    enunciado: "Em fluxos de trabalho colaborativos online (como documentos compartilhados no Google Docs ou Word Online via SharePoint/OneDrive), uma comissão precisa que: (1) os vereadores convidados possam apenas sugerir alterações e inserir comentários marginais sem alterar o texto consolidado diretamente; e (2) um estagiário possa apenas consultar o texto sem sequer baixar ou sugerir mudanças. Os papéis de acesso adequados a esses dois perfis são, respectivamente:",
