      "O fechamento definitivo do tráfego fluvial platino para embarcações estrangeiras e a transferência do eixo exportador mato-grossense para a ferrovia Cuiabá–Santarém.",
      "A substituição imediata do transporte fluvial pelo modal rodoviário federal pavimentado ao longo da BR-163 no final do século XIX.",
