    enunciado: "Na década de 1880, após atuar no abastecimento da comissão demarcadora de limites entre Brasil e Paraguai, o comerciante Thomaz Laranjeira obteve concessão imperial (Decreto nº 8.799/1882) que originou a Empresa/Companhia Mate Laranjeira. Sobre o impacto econômico e geopolítico desse empreendimento em Mato Grosso entre o final do Império e a Primeira República, assinale a alternativa CORRETA:",
