    sourceType: "Inédita Nível Top 10 (Padrão Selecon 2026)",
    enunciado: "Além da pecuária extensiva e do comércio ervateiro, a economia extrativista de Mato Grosso nas últimas décadas do século XIX e início do século XX apoiou-se fortemente na coleta de dois produtos florestais de alto valor comercial em frentes sertanejas distintas: o látex (borracha) e a raiz medicinal conhecida como poaia (ipecacuanha). Acerca dessas atividades econômicas, é CORRETO afirmar que:",
