    enunciado: "Na filosofia moral e na antropologia filosófica (conforme autores trabalhados em editais de nível médio como Marilena Chauí), a relação entre cultura e valores morais frequentemente opõe duas posturas extremas: o etnocentrismo e o relativismo cultural radical. Assinale a alternativa que define CORRETAMENTE essas duas posturas:",
