      "O etnocentrismo reconhece a igualdade de dignidade entre todas as tradições culturais, enquanto o relativismo cultural impõe padrões morais europeus como única medida civilizatória.",
      "Ambos os conceitos afirmam a existência de um código moral biológico imutável inscrito na natureza física de todas as sociedades humanas.",
